	/** A TArray with Size elements' worth of memory already reserved. */
	template <typename ArrayElementType>
	class TAllocatedArray : public TArray<ArrayElementType>
	{
	public:
		TAllocatedArray() = delete;

		explicit TAllocatedArray(int32 Size)
		{
			this->Reserve(Size);
		}
	};

